{
  "name": "pit",
  "version": "0.39.3",
  "description": "A single, dependency-injected TypeScript tool for Pi",
  "type": "module",
  "files": [
    "src",
    "prompts",
    "docs",
    "README.md",
    "CHANGELOG.md",
    "SECURITY.md",
    "LICENSE"
